  ('00000000-0000-0000-0000-000000000002', 'vendor', 'ভেন্ডর / সাপ্লায়ার', 'Vendor / Supplier', 'নিজস্ব কনসাইনমেন্ট পণ্য, স্টক এবং এসক্রো লেজার প্যানেল', 0, TRUE, TRUE),
